    explanation: '熱伝導率は物質のなかを熱がどれだけ伝わりやすいかを表す係数で、単位はW/(m・K)である。値が大きいほど熱をよく伝える。一般に固体が最も大きく、なかでも銀や銅などの金属が飛び抜けて大きい。液体はそれより小さく、気体は最も小さい。断熱材が繊維状で内部に空気を多く含む構造をしているのは、熱伝導率の小さい空気を動かないように閉じ込めることで熱の移動を抑えているからである。危険物の分野では、熱伝導率が小さい物質のなかでは発生した熱が逃げにくく蓄積するため、自然発火の危険が高まるという点が重要である。\n【図解】熱伝導率の大小関係\n　区分｜例｜熱伝導率\n　金属｜銅、アルミニウム｜非常に大きい\n　非金属固体｜ガラス、木材｜小さい\n　液体｜水、油｜さらに小さい\n　気体｜空気｜最も小さい\n　・断熱材は動かない空気を閉じ込めて熱を伝えにくくしている\n　⚠ 熱伝導率が小さい、イコール蓄熱しやすい、イコール自然発火の危険増',
