    explanation: '酸化と還元は、酸素、水素、電子のいずれに着目するかで表現が変わるが、いずれも同じ現象を別の面から述べたものである。酸化は酸素と化合すること、水素を失うこと、電子を失うこと、酸化数が増加することである。還元はその逆で、酸素を失うこと、水素と化合すること、電子を受け取ること、酸化数が減少することである。電子を失うのが酸化、受け取るのが還元という点は特に混同しやすい。また、電子は必ずどこかへ移動するので、酸化と還元は常に対になって同時に進行する。これを酸化還元反応という。\n【図解】酸化と還元の対応関係\n　着目点｜酸化される｜還元される\n　酸素｜化合する｜失う\n　水素｜失う｜化合する\n　電子｜失う｜受け取る\n　酸化数｜増加する｜減少する\n　⚠ 電子を失うのが酸化。受け取ると覚えると全問取り違える',
    difficulty: 'basic',
