    correctKey: 'D',
    explanation: 'イオン化傾向とは、金属が水溶液中で陽イオンになろうとする性質の強さである。大きい順に、カリウム、カルシウム、ナトリウム、マグネシウム、アルミニウム、亜鉛、鉄、ニッケル、スズ、鉛、水素、銅、水銀、銀、白金、金と並ぶ。イオン化傾向が大きい金属ほど電子を失いやすく、すなわち酸化されやすいので腐食しやすい。カリウムやナトリウムは常温の水とも激しく反応して水素を発生するため、第3類危険物として厳重に管理される。逆に金や白金はイオン化傾向が極めて小さく、酸にも侵されにくい。異種金属を接触させると、イオン化傾向の大きいほうが優先的に腐食する電食が生じる。\n【図解】イオン化傾向と反応性\n　イオン化傾向｜代表的な金属｜水との反応\n　非常に大きい｜カリウム、ナトリウム｜常温の水と激しく反応\n　大きい｜マグネシウム、アルミニウム｜熱水や高温水蒸気と反応\n　中程度｜亜鉛、鉄｜高温水蒸気と反応\n　小さい｜銅、銀、金｜反応しない\n　⚠ イオン化傾向が大きいほど腐食しやすい。逆に覚えない',
    difficulty: 'standard',
