    correctKey: 'A',
    explanation: '燃焼とは、熱と光の発生をともなう激しい酸化反応である。燃焼が起こるためには、燃える物である可燃物、酸化するための酸素供給源、そして反応を開始させるエネルギーである点火源の三つが必要であり、これを燃焼の三要素という。この三つのうち一つでも欠ければ燃焼は起こらず、燃焼中に一つを取り除けば消火できる。さらに、燃焼が継続するためには酸化反応の連鎖が続く必要があり、この連鎖反応を加えたものを燃焼の四要素という。抑制消火はこの連鎖反応を断ち切る消火方法である。\n【図解】燃焼の三要素と対応する消火法\n　要素｜具体例｜取り除く消火法\n　可燃物｜ガソリン、木材、紙｜除去消火\n　酸素供給源｜空気、酸化剤｜窒息消火\n　点火源｜火気、静電気、摩擦熱｜冷却消火\n　・三要素に連鎖反応を加えたものが燃焼の四要素\n　⚠ 窒素や二酸化炭素は酸素供給源にはならない',
