    correctKey: 'D',
    explanation: '燃焼の形態は可燃物の状態によって分類される。気体では、燃料と空気があらかじめ混ざってから燃える予混合燃焼と、混ざりながら燃える拡散燃焼がある。液体では、液面から蒸発した蒸気が空気と混ざって燃える蒸発燃焼が基本であり、第4類危険物はすべてこの形態である。固体では、加熱により分解して生じた可燃性ガスが燃える分解燃焼、蒸発してから燃える蒸発燃焼、固体表面で直接酸化する表面燃焼、そして分子内に酸素を含み外部の酸素なしでも燃える内部燃焼がある。ニトロセルロースやセルロイドは内部燃焼の代表例で、窒息消火が効きにくいという特徴をもつ。\n【図解】燃焼の形態と代表例\n　形態｜可燃物の状態｜代表例\n　蒸発燃焼｜液体、一部の固体｜ガソリン、硫黄、ナフタリン\n　分解燃焼｜固体｜木材、紙、石炭\n　表面燃焼｜固体｜木炭、コークス、金属粉\n　内部燃焼｜固体｜ニトロセルロース、セルロイド\n　⚠ 内部燃焼は窒息消火が効きにくい。酸素を自前で持っている',
    difficulty: 'standard',
