    correctKey: 'D',
    explanation: '防爆構造とは、可燃性ガスや蒸気が存在するおそれのある場所で使用する電気機器について、火花や高温部が点火源とならないよう設計された構造をいう。代表的なものに、内部で爆発が生じても容器が圧力に耐え、接合部のすきまで火炎を冷却して外部に伝えない耐圧防爆構造、容器内に空気や不活性ガスを送入して内圧を高め可燃性ガスの侵入を防ぐ内圧防爆構造、正常時に火花を発生しない部分を対象とする安全増防爆構造、点火に必要なエネルギー未満に電気回路を抑える本質安全防爆構造がある。ただし防爆構造は燃焼の三要素のうち点火源を断つ対策にすぎず、可燃性蒸気そのものを減らす換気や濃度管理を代替するものではない。\n【図解】主な防爆構造の種類\n　名称｜考え方｜特徴\n　耐圧防爆｜内部爆発に耐える｜火炎を外へ出さない\n　内圧防爆｜保護気体で加圧｜ガスを入れない\n　安全増防爆｜火花を出させない｜構造上の余裕をもたせる\n　本質安全防爆｜着火エネルギー未満｜回路自体を安全化\n　⚠ 防爆機器を使っても換気と濃度管理は省略できない',
