    explanation: '消火とは燃焼の継続に必要な条件を取り除くことであり、燃焼の四要素に対応して除去消火、窒息消火、冷却消火、抑制消火の四つがある。除去消火は可燃物を取り除く方法で、ガスの元栓を閉じる、ろうそくを吹き消すなどが例である。窒息消火は酸素の供給を断つ方法で、泡や二酸化炭素、砂による被覆が該当する。冷却消火は燃焼物から熱を奪い温度を引火点や発火点未満に下げる方法で、水による消火が代表である。抑制消火は燃焼の連鎖反応を化学的に断ち切る方法で、負触媒作用ともいい、ハロゲン化物消火剤や粉末消火剤がこれを担う。温度を上げる消火法というものは存在しない。\n【図解】消火の四要素と代表的な手段\n　消火法｜断つ要素｜代表的な手段\n　除去消火｜可燃物｜ガス栓を閉じる、可燃物を移す\n　窒息消火｜酸素供給源｜泡、二酸化炭素、乾燥砂\n　冷却消火｜熱（点火源）｜水、強化液\n　抑制消火｜連鎖反応｜ハロゲン化物、粉末\n　⚠ 加熱消火という消火法は存在しない',
