    explanation: '二酸化炭素消火剤は、放射された二酸化炭素が燃焼面を覆って周囲の酸素濃度を低下させる窒息効果を主な消火作用とする。液化二酸化炭素が気化する際の膨張と気化熱により多少の冷却効果もあるが、主体はあくまで窒息である。電気の不導体であり、消火後に薬剤が残らず機器を汚損しないため、電気設備や精密機器、通信機器の火災に適している。B火災、C火災に有効で、第4類危険物の火災にも用いられる。一方、酸素濃度を下げるという性質上、地下街や狭い密閉空間で使用すると人が窒息する危険があるため、法令上も使用場所が制限され、放射前の退避と警報が求められる。\n【図解】二酸化炭素消火剤の特徴\n　項目｜内容｜評価\n　主な作用｜窒息効果｜酸素濃度を下げる\n　副次的作用｜気化熱による冷却｜補助的\n　適応火災｜B火災、C火災｜油と電気に有効\n　注意点｜密閉空間での窒息｜地下街などは使用制限\n　⚠ 汚損しない利点の裏返しで、人への窒息危険がある',
    difficulty: 'standard',
