    correctKey: 'D',
    explanation: '消火器は充てんされた薬剤によって適応火災が定められており、本体に円形の標識で表示される。水消火器や強化液消火器の棒状放射はA火災に適応するが、電気火災には適さない。強化液を霧状に放射する消火器はA、B、C火災のすべてに適応する。機械泡消火器はA火災とB火災に適応するが、水分を含むため電気火災には適応しない。二酸化炭素消火器とハロゲン化物消火器はB火災とC火災に適応する。粉末消火器は主成分により分かれ、りん酸塩類ならA、B、C火災、炭酸水素塩類ならB、C火災に適応する。この対応表は本試験で繰り返し問われる。\n【図解】消火器の種類と適応火災\n　消火器｜A火災｜B火災とC火災\n　水（棒状）｜適応｜不適応\n　強化液（霧状）｜適応｜適応\n　機械泡｜適応｜B火災のみ適応\n　りん酸塩類の粉末｜適応｜適応\n　炭酸水素塩類の粉末｜不適応｜適応\n　⚠ 粉末は主成分でA火災への適否が分かれる',
