    correctKey: 'B',
    explanation: '炭素の完全燃焼の反応式は C＋O2 が CO2 になる、である。炭素の原子量は12であるから、12 gはちょうど1 molにあたる。反応式の係数比より、炭素1 molからは二酸化炭素が1 mol生じる。二酸化炭素の分子量は12＋16×2＝44であるから、生じる二酸化炭素は44 gである。なお必要な酸素は1 molすなわち32 gであり、質量保存の法則により 12＋32＝44 と両辺の質量が一致することが確認できる。不完全燃焼であれば一酸化炭素28 gが生じる場合もあり、生成物が異なることに注意する。\n【図解】炭素の完全燃焼の量的関係\n　物質｜物質量｜質量\n　炭素C｜1 mol｜12 g\n　酸素O2｜1 mol｜32 g\n　二酸化炭素CO2｜1 mol｜44 g\n　式：C＋O2 から CO2 が生じる\n　質量保存：12＋32＝44\n　答え：44 g\n　⚠ 質量保存で検算できる。左辺と右辺の合計は必ず一致する',
