    correctKey: 'C',
    explanation: '可燃物とは酸化されて燃える物質のことである。木材、紙、繊維などの一般可燃物、硫黄や金属粉などの第2類危険物、ガソリンなどの第4類危険物はいずれも可燃物である。これに対し、すでに酸化が完了していてそれ以上酸化されない物質は不燃物である。二酸化炭素は炭素が完全に酸化された最終形であり、これ以上燃えないので消火剤として利用される。同様に水、窒素、酸化アルミニウム、リン酸なども不燃物である。紛らわしいのが一酸化炭素で、炭素の酸化が途中で止まった状態であるためさらに燃えることができ、燃焼範囲も広い立派な可燃物である。\n【図解】可燃物と不燃物の見分け\n　区分｜例｜理由\n　可燃物｜木材、硫黄、ガソリン｜酸化されて燃える\n　可燃物｜一酸化炭素、水素｜さらに酸化できる\n　不燃物｜二酸化炭素、水、窒素｜酸化が完了または不活性\n　不燃物｜ガラス、石｜そもそも酸化されない\n　⚠ 一酸化炭素は可燃物。二酸化炭素と混同しない',
