    explanation: '固体の燃焼形態は四つに整理できる。表面燃焼は、木炭、コークス、金属粉のように、熱分解も蒸発もせず固体表面で酸素と直接反応して燃える形態で、炎を出さず赤熱するのが特徴である。分解燃焼は、木材、紙、石炭、プラスチックのように、加熱によって熱分解し発生した可燃性ガスが燃える形態である。蒸発燃焼は、硫黄、ナフタリン、固形アルコールのように、固体がいったん蒸発して蒸気が燃える形態である。内部燃焼は自己燃焼ともいい、ニトロセルロースやセルロイドのように分子内に酸素を含み、外部からの酸素供給がなくても燃焼が継続する形態である。\n【図解】固体の燃焼形態と代表例\n　形態｜代表例｜特徴\n　表面燃焼｜木炭、コークス、金属粉｜炎を出さず赤熱する\n　分解燃焼｜木材、紙、石炭、プラスチック｜熱分解ガスが燃える\n　蒸発燃焼｜硫黄、ナフタリン、固形アルコール｜いったん蒸発する\n　内部燃焼｜ニトロセルロース、セルロイド｜分子内に酸素をもつ\n　⚠ 木材は分解燃焼。蒸発燃焼と取り違える出題が多い',
