    explanation: '燃焼のしやすさは複数の要因で決まる。酸素と結びつきやすい、すなわち酸化されやすいこと、発熱量が大きいこと、表面積が大きいこと、熱伝導率が小さいこと、乾燥していて含水量が少ないこと、周囲の温度が高いこと、可燃性蒸気を発生しやすいことが、いずれも燃えやすさを高める。逆に水分を多く含むと、加熱された熱がまず水の蒸発に使われてしまうため温度が上がりにくく、燃えにくくなる。この整理は自然発火の条件や粉じん爆発の条件と共通しており、まとめて理解すると記憶しやすい。\n【図解】燃えやすさを高める条件\n　要因｜燃えやすいのは｜理由\n　発熱量｜大きいほど｜自己加熱が進む\n　表面積｜大きいほど｜酸素との接触が増える\n　熱伝導率｜小さいほど｜熱が逃げず温度が上がる\n　含水量｜少ないほど｜蒸発に熱を取られない\n　⚠ 水分が多いほど燃えやすいという記述は方向が逆',
    difficulty: 'basic',
