    correctKey: 'C',
    explanation: '有機化合物は骨格の形によって、鎖状の脂肪族化合物とベンゼン環をもつ芳香族化合物に大別される。炭素と水素だけからなるものを炭化水素といい、炭素間の結合がすべて単結合であるものを飽和炭化水素、二重結合や三重結合を含むものを不飽和炭化水素という。飽和炭化水素の代表はメタンやプロパンなどのアルカンで、比較的安定である。不飽和炭化水素は反応性が高く、付加反応を起こしやすい。乾性油のヨウ素価が高いのは、この不飽和結合が多く酸素と反応しやすいためである。第4類危険物にはガソリンや灯油のような脂肪族炭化水素の混合物と、ベンゼンやトルエンのような芳香族の両方が含まれる。\n【図解】有機化合物の分類\n　分類の軸｜区分｜例\n　骨格の形｜脂肪族｜メタン、エタノール、酢酸\n　骨格の形｜芳香族｜ベンゼン、トルエン、キシレン\n　結合の種類｜飽和｜メタン、プロパン\n　結合の種類｜不飽和｜エチレン、アセチレン\n　⚠ 二重結合があれば不飽和。飽和と書かれていたら誤り',
