    correctKey: 'D',
    explanation: 'アルコールはヒドロキシ基をもつ有機化合物である。ヒドロキシ基は水分子と水素結合をつくるため水になじみやすいが、炭素数が増えると水になじまない炭化水素部分の割合が大きくなり、水への溶解性は低下する。メタノールやエタノールは水と自由に混ざるが、炭素数が増えると溶けにくくなる。危険物の分類では、炭素数1から3の飽和1価アルコールがアルコール類とされる。メタノールは引火点11度、発火点約385度、燃焼範囲6.0から36パーセントで、毒性が強く飲用すると失明や死に至る。エタノールは引火点13度、燃焼範囲3.3から19パーセントである。いずれも水溶性なので消火には水溶性液体用泡を用いる。\n【図解】メタノールとエタノールの比較\n　項目｜メタノール｜エタノール\n　引火点｜11度｜13度\n　燃焼範囲｜6.0から36パーセント｜3.3から19パーセント\n　毒性｜強い｜比較的弱い\n　水溶性｜自由に混ざる｜自由に混ざる\n　⚠ 炭素数が増えると水に溶けにくくなる。逆に覚えない',
