    correctKey: 'A',
    explanation: 'アセトアルデヒドは第4類の特殊引火物に分類される。沸点が約20度と常温付近であるため、夏季には液体が沸騰して大量の蒸気を発生する。引火点はマイナス39度、発火点は約175度、燃焼範囲は約4.0から60パーセントと非常に広く、極めて危険性が高い。水にもアルコールにもよく溶ける水溶性の物質であるから、火災には水溶性液体用泡を用いる必要がある。また酸化されやすく、空気に触れると酢酸を生じる。加圧下では容器の内圧が高まるため、貯蔵には冷却設備や不活性ガスによる封入が求められる。銅やその合金を腐食し爆発性の物質をつくるおそれがあるため、それらの材質の容器や配管は避ける。\n【図解】アセトアルデヒドの主な性状\n　項目｜数値や性質｜取扱いの要点\n　沸点｜約20度｜常温で沸騰することがある\n　引火点｜マイナス39度｜常温で引火する\n　燃焼範囲｜4.0から60パーセント｜極めて広い\n　水溶性｜よく溶ける｜水溶性液体用泡を使う\n　⚠ 水に溶けるので一般の泡は消泡される。泡の種類に注意',
