    correctKey: 'D',
    explanation: '反応熱は、どのような反応に着目するかによって呼び名が変わる。燃焼熱は物質1 molが完全燃焼するときに発生する熱量で、常に発熱である。生成熱は化合物1 molが成分元素の単体から生じるときの熱量、中和熱は中和によって水1 molを生じるときの熱量で、強酸と強塩基の組合せではおよそ56 kJ/molとほぼ一定になる。溶解熱は物質1 molを多量の溶媒に溶かすときに出入りする熱量で、発熱の場合も吸熱の場合もある。濃硫酸を水で希釈すると激しく発熱するため、必ず水に酸を少しずつ加えるという手順が守られる。逆にすると突沸して飛散する危険がある。\n【図解】反応熱の種類\n　名称｜定義｜熱の向き\n　燃焼熱｜1 molの完全燃焼｜必ず発熱\n　生成熱｜単体から化合物1 molを生成｜発熱も吸熱もある\n　中和熱｜水1 molを生じる中和｜発熱\n　溶解熱｜1 molを溶媒に溶かす｜発熱も吸熱もある\n　⚠ 濃硫酸の希釈は水に酸を加える。逆は突沸して危険',
