    explanation: '地下に埋設された金属配管は、土壌中の水分や塩分によって電気化学的な腐食を受ける。これを防ぐ方法が電気防食で、配管を電気化学的に陰極の状態に保つことで金属の溶出を止める。方式には二つある。流電陽極法は、配管よりイオン化傾向の大きい卑な金属であるマグネシウムや亜鉛を接続し、それを犠牲的に溶解させることで配管を守る方法で、電源が不要という利点がある。外部電源法は、外部の直流電源から防食電流を流す方法で、長距離や大規模な設備に適する。いずれの場合も塗覆装との併用が原則であり、被覆で大部分を守ったうえで、傷や欠陥部を電気防食が補うという考え方をとる。\n【図解】電気防食の二方式\n　方式｜仕組み｜特徴\n　流電陽極法｜卑な金属を犠牲にする｜電源不要、小規模向け\n　外部電源法｜直流電源で防食電流を流す｜長距離、大規模向け\n　共通の考え方｜配管を陰極にする｜陰極防食ともいう\n　併用｜塗覆装と組み合わせる｜必要な電流を減らせる\n　⚠ 電気防食があっても塗覆装は省略できない',
    difficulty: 'advanced',
