    explanation: '冷却であっても計算式は加熱と同じ Q＝m×c×Δt を用い、温度差の絶対値を代入する。質量5 kgは5,000 g、比熱は4.2 J/(g・K)、温度差は90から30を引いた60 Kである。したがって Q＝5,000×4.2×60＝1,260,000 J＝1,260 kJとなる。この熱量が水から奪われることになる。冷却消火の考え方では、燃焼物の温度を引火点や発火点より下げるために、これだけの熱を吸収できる量の水を用意する必要があるという見積もりに使われる。桁が大きくなるので、JとkJの換算を最後に必ず確認する。\n【図解】冷却に必要な熱量の計算\n　量｜記号｜値\n　質量｜m｜5,000 g\n　比熱｜c｜4.2 J/(g・K)\n　温度差｜Δt｜60 K\n　式：Q＝m×c×Δt\n　代入：5,000×4.2×60＝1,260,000\n　答え：1,260,000 J＝1,260 kJ\n　⚠ 冷却でも式は同じ。温度差は必ず引き算で求める',
