    correctKey: 'C',
    explanation: '燃焼下限値とは、可燃性蒸気と空気の混合気が燃焼できる最も低い蒸気濃度である。これより薄い混合気は燃料が不足しているため、どれほど強い点火源を与えても燃焼は継続しない。引火点は、液面上に生じる蒸気の濃度がちょうどこの燃焼下限値に達する最低の液温として定義される。したがって引火点と燃焼下限値は表裏一体の関係にある。燃焼下限値が低い物質ほど、少ない蒸気で燃焼範囲に入るため危険性が高い。ガソリンの下限値は1.4パーセント、灯油は1.1パーセントであり、いずれも低い値である。また温度が上がると一般に下限値は下がり燃焼範囲は広がる。\n【図解】燃焼下限値と引火点の関係\n　項目｜内容｜危険性\n　燃焼下限値｜燃える最低の蒸気濃度｜低いほど危険\n　引火点｜蒸気濃度が下限値に達する液温｜低いほど危険\n　下限値未満｜燃料不足｜点火源があっても燃えない\n　温度上昇｜下限値は下がる｜燃焼範囲は広がる\n　⚠ 下限値未満なら強い点火源でも燃えない。濃度が支配的',
