    correctKey: 'A',
    explanation: '第4類危険物の蒸気は、ほとんどが空気より重い。ガソリンで3から4、灯油で4.5程度、トルエンで約3.2、二硫化炭素で約2.6であり、いずれも1を大きく超える。したがって蒸気は床面付近、ピット、排水溝、地下ピットなど低い場所に流れ込んで滞留する。この滞留した蒸気が離れた場所の点火源まで達して引火する事故が実際に起きている。対策としては、低所からの排気を確実に行うこと、ピットや溝に蒸気を溜めないこと、低い位置に点火源を置かないことが重要である。天井付近だけの換気では低所の蒸気を排出できないので不十分である。\n【図解】重い蒸気への対策\n　注意すべき場所｜理由｜対策\n　床面付近｜蒸気が沈む｜低所排気を設ける\n　ピット、排水溝｜蒸気が流れ込む｜蓋、封水、換気\n　地下室、くぼ地｜屋外でも溜まる｜立入りと点火源を制限\n　高所の換気口｜重い蒸気は届かない｜低所と併用する\n　⚠ 換気口の位置を誤ると換気の意味がなくなる',
    difficulty: 'basic',
