    correctKey: 'B',
    explanation: 'アボガドロの法則は、同温同圧のもとでは同体積の気体は種類によらず同数の分子を含むことを述べる。この法則から、標準状態では気体1 molがどれも22.4 Lを占めるという関係が導かれる。また同体積の気体の質量の比が分子量の比に等しくなるため、蒸気比重を分子量を空気の平均分子量29で割って求めることができる。1 molに含まれる粒子の数は約6.02×10の23乗個で、これをアボガドロ定数という。この値は物質の種類によらず一定である。気体の体積、質量、物質量を相互に換算する計算の土台となる重要な法則である。\n【図解】アボガドロの法則から導かれること\n　導かれる関係｜内容｜利用\n　標準状態の体積｜1 molが22.4 L｜体積と物質量の換算\n　質量比｜分子量の比に等しい｜蒸気比重の計算\n　アボガドロ定数｜約6.02×10の23乗個｜粒子数の換算\n　・同体積で同じなのは分子の数であって質量ではない\n　⚠ 同数なのは分子の数。質量が同じという記述は誤り',
